begin;
create temporary table coding_question_seed(collection_slug text not null,slug text not null,title text not null,problem_statement text not null,difficulty text not null,topic_tags text[] not null,constraints jsonb not null,examples jsonb not null,starter_code_by_language jsonb not null,points integer not null) on commit drop;
insert into coding_question_seed select collection_slug,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points from jsonb_to_recordset($seed$[{"collection_slug":"go-programming","slug":"parse-env-lines-go","title":"Parse Environment Lines","problem_statement":"Parse nonblank KEY=VALUE lines, trimming spaces. Keys must match uppercase letters, digits, or underscores and be unique; malformed or duplicate entries return an error.","difficulty":"Medium","topic_tags":["Parsing and Errors","Go"],"constraints":["0 <= lines.length <= 10000","Keys use ASCII A-Z, digits, or underscore; duplicate keys invalidate the whole result."],"examples":[{"input":"[\"HOST = api\",\"PORT=8080\"]","output":"{\"HOST\":\"api\",\"PORT\":\"8080\"},nil"},{"input":"[\"A=1\",\"A=2\"]","output":"error"}],"starter_code_by_language":{"Go":"func ParseEnvLines(lines []string) (map[string]string, error) {\n\t// Parse Environment Lines.\n\treturn nil, nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"merge-flight-bookings-go","title":"Merge Flight Seat Bookings","problem_statement":"BookingRequest contains Flight and Seats. Process requests in order, accepting only positive seat counts that keep the flight at or below capacity 180. Return a copy of the input map.","difficulty":"Medium","topic_tags":["Maps and Modeling","Go"],"constraints":["Each flight capacity is 180 seats; request counts may be zero or negative.","Process all requests in input order without mutating the bookings map."],"examples":[{"input":"bookings={AZ12:178}, requests=[AZ12:1,AZ12:3]","output":"{AZ12:179}"},{"input":"bookings={Q7:90}, requests=[Q7:100]","output":"{Q7:90}"}],"starter_code_by_language":{"Go":"type BookingRequest struct { Flight string; Seats int }\nfunc MergeBookings(bookings map[string]int, requests []BookingRequest) map[string]int {\n\t// Merge Flight Seat Bookings.\n\treturn nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"longest-distinct-rune-window-go","title":"Longest Distinct Rune Window","problem_statement":"Return the maximum number of Unicode code points in a contiguous substring containing no repeated rune; byte length is not the requested measure.","difficulty":"Medium","topic_tags":["Unicode and Sliding Window","Go"],"constraints":["0 <= len(text) <= 100000 UTF-8 bytes.","Count Unicode code points, not bytes or UTF-16 units."],"examples":[{"input":"\"a??b??c\"","output":"3"},{"input":"\"??\"","output":"1"}],"starter_code_by_language":{"Go":"func LongestDistinctRuneWindow(text string) int {\n\t// Longest Distinct Rune Window.\n\treturn 0\n}"},"points":150},{"collection_slug":"go-programming","slug":"parse-csv-record-go","title":"Parse One CSV Record","problem_statement":"Parse one CSV record with quoted fields, doubled-quote escaping, and commas inside quoted fields. Reject unterminated quotes and non-comma text after a closing quote.","difficulty":"Hard","topic_tags":["Parsing and State Machines","Go"],"constraints":["0 <= len(line) <= 100000 bytes; fields may be empty.","Quoted fields use doubled quotes for escaping; malformed quoting returns an error."],"examples":[{"input":"a,\"b,c\",\"d\"\"e\"","output":"[\"a\",\"b,c\",\"d\\\"e\"],nil"},{"input":"name,\"New York\"","output":"[\"name\",\"New York\"],nil"}],"starter_code_by_language":{"Go":"func ParseCSVRecord(line string) ([]string, error) {\n\t// Parse One CSV Record.\n\treturn nil, nil\n}"},"points":200},{"collection_slug":"go-programming","slug":"evaluate-rpn-go","title":"Evaluate Reverse Polish Notation","problem_statement":"Evaluate signed integer tokens and binary +,-,*,/ operators in postfix order. Division truncates toward zero; malformed expressions and division by zero return an error.","difficulty":"Medium","topic_tags":["Stacks and Errors","Go"],"constraints":["1 <= len(tokens) <= 100000; token operands fit int64.","Intermediate overflow, invalid arity, and division by zero return an error."],"examples":[{"input":"[\"8\",\"3\",\"-\"]","output":"5,nil"},{"input":"[\"7\",\"2\",\"/\"]","output":"3,nil"}],"starter_code_by_language":{"Go":"func EvaluateRPN(tokens []string) (int64, error) {\n\t// Evaluate Reverse Polish Notation.\n\treturn 0, nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"shortest-word-ladder-go","title":"Shortest Word Transformation","problem_statement":"Return the number of words in a shortest transformation from begin to end, changing one lowercase letter per step and using only words in the dictionary. Return zero if impossible.","difficulty":"Hard","topic_tags":["Breadth-First Search","Go"],"constraints":["All words are distinct lowercase ASCII strings of the same length; at most 5000 dictionary words.","A transformation changes exactly one character and every intermediate word, including end, must be in words."],"examples":[{"input":"\"hit\",\"cog\",[\"hot\",\"dot\",\"dog\",\"lot\",\"log\",\"cog\"]","output":"5"},{"input":"\"cat\",\"dog\",[\"cot\",\"cog\",\"dog\"]","output":"4"}],"starter_code_by_language":{"Go":"func WordLadderLength(begin, end string, words []string) int {\n\t// Shortest Word Transformation.\n\treturn 0\n}"},"points":200},{"collection_slug":"go-programming","slug":"merge-k-sorted-streams-go","title":"Merge Sorted Integer Streams","problem_statement":"Merge any number of ascending integer slices into one ascending result. Preserve every duplicate value and do not mutate source slices.","difficulty":"Hard","topic_tags":["Heaps and Slices","Go"],"constraints":["There are at most 10000 sorted input slices and 100000 total values.","Inputs are ascending; preserve duplicate multiplicity and do not mutate inputs."],"examples":[{"input":"[[1,4,9],[1,3,10],[2,2]]","output":"[1,1,2,2,3,4,9,10]"},{"input":"[[0],[],[-2,5]]","output":"[-2,0,5]"}],"starter_code_by_language":{"Go":"func MergeSortedStreams(streams [][]int) []int {\n\t// Merge Sorted Integer Streams.\n\treturn nil\n}"},"points":200},{"collection_slug":"go-programming","slug":"course-dependency-order-go","title":"Course Dependency Order","problem_statement":"Each dependency [course, prerequisite] requires prerequisite first. Return a valid order and true, or an empty slice and false if the graph has a cycle.","difficulty":"Hard","topic_tags":["Graphs and Topological Sort","Go"],"constraints":["0 <= count <= 100000; each valid dependency references distinct in-range vertices.","Return any topological order; cycles must be reported with false and no partial order."],"examples":[{"input":"4,[[1,0],[2,0],[3,1],[3,2]]","output":"[0,1,2,3],true"},{"input":"2,[[0,1],[1,0]]","output":"[],false"}],"starter_code_by_language":{"Go":"func CourseOrder(count int, dependencies [][2]int) ([]int, bool) {\n\t// Course Dependency Order.\n\treturn nil, false\n}"},"points":200},{"collection_slug":"go-programming","slug":"apply-idempotent-ledger-go","title":"Apply Idempotent Ledger Entries","problem_statement":"Apply entries in order, counting each ID only once. Reject empty IDs or accounts, and return an error if an account balance would overflow int64. Return balances by account.","difficulty":"Hard","topic_tags":["Structs, Maps, and Errors","Go"],"constraints":["At most 100000 entries; IDs and account names are case-sensitive.","Apply first occurrence of an ID only; reject empty identifiers and int64 overflow."],"examples":[{"input":"[{x,lee,12},{x,lee,12},{y,lee,-5}]","output":"{lee:7},nil"},{"input":"[{a,kim,4},{b,kim,-1}]","output":"{kim:3},nil"}],"starter_code_by_language":{"Go":"type LedgerEntry struct {\n\tID, Account string\n\tDelta int64\n}\n\nfunc ApplyLedger(entries []LedgerEntry) (map[string]int64, error) {\n\t// Apply Idempotent Ledger Entries.\n\treturn nil, nil\n}"},"points":200},{"collection_slug":"go-programming","slug":"simulate-token-bucket-go","title":"Simulate a Token Bucket","problem_statement":"Start with a full bucket. Before each request add refill tokens up to capacity; accept if cost is nonnegative and affordable, subtracting accepted cost. Return one decision per request.","difficulty":"Medium","topic_tags":["State Modeling","Go"],"constraints":["Capacity, refill, and costs are nonnegative integers; at most 100000 requests.","Each refill occurs before its request and bucket contents never exceed capacity."],"examples":[{"input":"capacity=5,refill=2,costs=[4,4,1]","output":"[true,false,true]"},{"input":"capacity=3,refill=1,costs=[4,2]","output":"[false,true]"}],"starter_code_by_language":{"Go":"func SimulateTokenBucket(capacity, refill int, costs []int) []bool {\n\t// Simulate a Token Bucket.\n\treturn nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"run-lru-cache-commands-go","title":"Run LRU Cache Commands","problem_statement":"Support put and get. Gets append the value or -1 to output. Successful gets and puts mark the key most-recent; evict the least-recent key after overflow. Capacity zero stores nothing.","difficulty":"Hard","topic_tags":["Maps and Linked Lists","Go"],"constraints":["Commands are put or get; capacity is a nonnegative integer.","A put of an existing key updates its value and recency; capacity zero stores nothing."],"examples":[{"input":"cap=2; put(1,8),put(2,9),get(1),put(3,7),get(2),get(3)","output":"[8,-1,7]"},{"input":"cap=1; put(4,6),get(4),put(5,2),get(4)","output":"[6,-1]"}],"starter_code_by_language":{"Go":"type CacheCommand struct {\n\tOp string\n\tKey, Value int\n}\n\nfunc RunLRU(capacity int, commands []CacheCommand) []int {\n\t// Run LRU Cache Commands.\n\treturn nil\n}"},"points":200},{"collection_slug":"go-programming","slug":"retry-delay-schedule-go","title":"Capped Exponential Retry Delays","problem_statement":"Produce attempts delays beginning at base and doubling each time, never exceeding maximum. Avoid integer overflow during doubling; zero attempts returns an empty slice.","difficulty":"Easy","topic_tags":["Reliability and Overflow","Go"],"constraints":["0 <= attempts <= 1000 and 1 <= base <= maximum <= MaxInt64.","Each delay doubles with saturation at maximum, without overflow."],"examples":[{"input":"base=100,maximum=350,attempts=5","output":"[100,200,350,350,350]"},{"input":"base=7,maximum=20,attempts=3","output":"[7,14,20]"}],"starter_code_by_language":{"Go":"func RetryDelays(base, maximum int64, attempts int) []int64 {\n\t// Capped Exponential Retry Delays.\n\treturn nil\n}"},"points":100},{"collection_slug":"go-programming","slug":"valid-utf8-input-go","title":"Validate UTF-8 Byte Sequence","problem_statement":"Return whether bytes are well-formed UTF-8, rejecting truncated encodings, overlong forms, surrogate code points, invalid leading bytes, and values above U+10FFFF.","difficulty":"Medium","topic_tags":["Unicode and Validation","Go"],"constraints":["Input contains at most 100000 bytes.","All UTF-8 validity restrictions, including overlong forms and surrogate encodings, apply."],"examples":[{"input":"[0x47,0x6f]","output":"true"},{"input":"[0xC0,0xAF]","output":"false"}],"starter_code_by_language":{"Go":"func IsValidUTF8(data []byte) bool {\n\t// Validate UTF-8 Byte Sequence.\n\treturn false\n}"},"points":150},{"collection_slug":"go-programming","slug":"first-unique-rune-go","title":"Find First Unique Rune","problem_statement":"Return the first Unicode rune that occurs exactly once together with true; if every rune repeats, return zero rune and false.","difficulty":"Easy","topic_tags":["Maps and Unicode","Go"],"constraints":["0 <= len(text) <= 100000 UTF-8 bytes.","Occurrence counts are by Unicode rune and original order determines the answer."],"examples":[{"input":"\"swiss\"","output":"w,true"},{"input":"\"aabbcc\"","output":"0,false"}],"starter_code_by_language":{"Go":"func FirstUniqueRune(text string) (rune, bool) {\n\t// Find First Unique Rune.\n\treturn 0, false\n}"},"points":100},{"collection_slug":"go-programming","slug":"coalesce-maintenance-windows-go","title":"Coalesce Maintenance Windows","problem_statement":"Treat each pair as a half-open time window. Sort by start, merge overlapping or adjacent windows, and discard empty windows.","difficulty":"Medium","topic_tags":["Intervals","Go"],"constraints":["At most 100000 windows; endpoints are signed integers.","Windows are half-open; zero-length windows are removed and touching windows coalesce."],"examples":[{"input":"[[8,10],[1,3],[3,5],[6,6]]","output":"[[1,5],[8,10]]"},{"input":"[[2,7],[5,9]]","output":"[[2,9]]"}],"starter_code_by_language":{"Go":"func CoalesceWindows(windows [][2]int) [][2]int {\n\t// Coalesce Maintenance Windows.\n\treturn nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"count-lines-from-reader-go","title":"Count Lines from an io.Reader","problem_statement":"Read from an io.Reader and count logical lines. A newline terminates a line; count a final nonempty unterminated line once, and propagate any non-EOF read error rather than returning a partial count.","difficulty":"Medium","topic_tags":["io.Reader Interface","Errors","Go"],"constraints":["The reader may return short reads and may provide data and an error in the same Read call.","Count a trailing newline as a terminator, not as an additional empty line; an empty stream has zero lines."],"examples":[{"input":"reader contains \"oak\\npine\\n\"","output":"2,nil"},{"input":"reader contains \"cedar\"","output":"1,nil"}],"starter_code_by_language":{"Go":"import \"io\"\n\nfunc CountLinesFromReader(reader io.Reader) (int, error) {\n\t// Count complete lines and propagate reader errors.\n\treturn 0, nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"minimum-jumps-to-target-go","title":"Minimum Jumps to Array End","problem_statement":"At index i, maxSteps[i] is the maximum forward distance. Return the fewest jumps to the final index, or -1 if it cannot be reached. Empty or singleton input needs zero jumps.","difficulty":"Medium","topic_tags":["Greedy Algorithms","Go"],"constraints":["0 <= len(maxSteps) <= 100000; every jump limit is nonnegative.","Return zero for zero or one element, and -1 when the final index is unreachable."],"examples":[{"input":"[2,3,1,1,4]","output":"2"},{"input":"[3,2,1,0,4]","output":"-1"}],"starter_code_by_language":{"Go":"func MinimumJumps(maxSteps []int) int {\n\t// Minimum Jumps to Array End.\n\treturn 0\n}"},"points":150},{"collection_slug":"go-programming","slug":"validate-profile-errors-go","title":"Collect Profile Validation Errors","problem_statement":"Return every applicable code in this order: empty-name, invalid-email unless exactly one @ has nonempty sides, age-out-of-range unless age is 0 through 130. Do not stop at the first failure.","difficulty":"Medium","topic_tags":["Validation and Error Reporting","Go"],"constraints":["Name and email are at most 10000 bytes; age is any int.","Return every failing code in the documented fixed order rather than stopping early."],"examples":[{"input":"\"\", \"a@b\", 22","output":"[\"empty-name\"]"},{"input":"\"Jo\", \"bad\", 140","output":"[\"invalid-email\",\"age-out-of-range\"]"}],"starter_code_by_language":{"Go":"func ValidateProfile(name, email string, age int) []string {\n\t// Collect Profile Validation Errors.\n\treturn nil\n}"},"points":150},{"collection_slug":"go-programming","slug":"concurrent-map-results-go","title":"Order-Preserving Parallel Transform","problem_statement":"Compute the square of every input using at most workers goroutines, but return results in original order. workers is positive; each square fits int. The implementation must not leak workers when input is empty.","difficulty":"Hard","topic_tags":["Concurrency and Channels","Go"],"constraints":["workers > 0; each square fits in int; at most 100000 values.","Use no more than workers goroutines and preserve input order in returned results."],"examples":[{"input":"[3,-2,5], workers=2","output":"[9,4,25]"},{"input":"[-1,0], workers=1","output":"[1,0]"}],"starter_code_by_language":{"Go":"func ParallelSquares(values []int, workers int) []int {\n\t// Order-Preserving Parallel Transform.\n\treturn nil\n}"},"points":200},{"collection_slug":"go-programming","slug":"reduce-account-events-go","title":"Reduce Account Balance Events","problem_statement":"Apply deltas sequentially. Return an error if any intermediate balance becomes negative or overflows int64; otherwise return the final balance.","difficulty":"Hard","topic_tags":["Event Modeling and Errors","Go"],"constraints":["At most 100000 int64 deltas; initial balance is nonnegative.","Every intermediate result must fit int64 and remain nonnegative."],"examples":[{"input":"10,[-3,5]","output":"12,nil"},{"input":"2,[-3]","output":"0,error"}],"starter_code_by_language":{"Go":"func ReduceBalance(initial int64, deltas []int64) (int64, error) {\n\t// Reduce Account Balance Events.\n\treturn 0, nil\n}"},"points":200}]$seed$) as s(collection_slug text,slug text,title text,problem_statement text,difficulty text,topic_tags text[],constraints jsonb,examples jsonb,starter_code_by_language jsonb,points integer);
do $validate_seed$ begin
if (select count(*) from coding_question_seed)<>20 or (select count(distinct slug) from coding_question_seed)<>20 or exists(select 1 from coding_question_seed where collection_slug<>'go-programming') then raise exception 'Expected exactly 20 unique Go question rows'; end if;
if exists(select 1 from coding_question_seed where slug in ('slice-append','sum-array','map-from-slice','prime-check','count-characters','first-missing-positive-go','rotate-slice-left-go')) then raise exception 'Existing Go slug collision'; end if;
if (select count(distinct title) from coding_question_seed)<>20 or exists(select 1 from coding_question_seed where char_length(btrim(title))<8 or char_length(btrim(problem_statement))<100 or difficulty not in ('Easy','Medium','Hard') or jsonb_typeof(constraints)<>'array' or jsonb_array_length(constraints)<2 or jsonb_typeof(examples)<>'array' or jsonb_array_length(examples)<2 or jsonb_typeof(starter_code_by_language)<>'object' or not starter_code_by_language ? 'Go' or points not between 0 and 1000 or problem_statement ~* '(implement the described transformation|named operation|input candidates|placeholder|TODO)') then raise exception 'Go completeness or placeholder validation failed'; end if;
if exists(select 1 from coding_question_seed s where exists(select 1 from jsonb_array_elements(s.examples) e where nullif(btrim(e->>'input'),'') is null or nullif(btrim(e->>'output'),'') is null or btrim(e->>'input') in ('[]','[null]','null'))) then raise exception 'Go examples must be meaningful input/output pairs'; end if;
if not exists(select 1 from public.coding_test_sets where slug='go-programming' and publication_status='published') then raise exception 'Published Go collection missing'; end if; end; $validate_seed$;
with question_rows as (select c.id collection_id,s.*,coalesce(m.max_order,0)+row_number() over(partition by c.id order by s.slug)::integer question_order from coding_question_seed s join public.coding_test_sets c on c.slug=s.collection_slug and c.publication_status='published' cross join lateral(select max(q.question_order) max_order from public.coding_questions q where q.collection_id=c.id) m) insert into public.coding_questions(collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order) select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order from question_rows on conflict(collection_id,slug) do nothing;
insert into public.coding_test_cases(question_id,case_order,test_input,expected_output,visibility) select q.id,e.ordinality::integer,e.value->>'input',e.value->>'output','visible' from coding_question_seed s join public.coding_test_sets c on c.slug=s.collection_slug join public.coding_questions q on q.collection_id=c.id and q.slug=s.slug cross join lateral jsonb_array_elements(s.examples) with ordinality e(value,ordinality) on conflict(question_id,case_order) do nothing;
commit;
